1	/**
2	 * The whole screen: the launchpad, and the map you open from it.
3	 *
4	 * Two states and nothing in between. The launchpad names the two ways into the
5	 * tool and offers the four examples from the brief; opening the one that is
6	 * built swaps the page for the map. Everything on the map came over the wire
7	 * from the server, and the line under it says which address it came from — this
8	 * product does not put a number on screen that a reader cannot trace to an
9	 * input, a rule or a source, and that includes numbers a stored example happens
10	 * to carry.
11	 *
12	 * There is no spinner anywhere, and there never will be. A spinner says "wait"
13	 * without saying what for. While something is on its way the screen says what
14	 * it is waiting for and where it asked.
15	 */
16	
17	import { useCallback, useEffect, useMemo, useRef, useState } from "react";
18	import { branchAnnouncement } from "./a11y/announcement";
19	import { growthAnnouncement } from "./a11y/growth";
20	import { outlineOf } from "./a11y/sentences";
21	import type { About, FixtureSummary, Health } from "./api/client";
22	import { RefusedBranch, readAbout, readExampleList, readHealth, readReadiness } from "./api/client";
23	import { AddAClaim } from "./components/AddAClaim";
24	import { BranchPanel, InterventionPanel } from "./components/BranchPanel";
25	import { type Command, CommandPalette } from "./components/CommandPalette";
26	import { DeltaRail } from "./components/DeltaRail";
27	import { DoneLine } from "./components/DoneLine";
28	import type { Asked } from "./components/InputBar";
29	import { Inspector } from "./components/Inspector";
30	import { Launchpad } from "./components/Launchpad";
31	import { Outline } from "./components/Outline";
32	import { ReceiptStrip } from "./components/ReceiptStrip";
33	import { Refusal } from "./components/Refusal";
34	import { RefusalStrip } from "./components/RefusalStrip";
35	import { ReplayBadge, replaySentence } from "./components/ReplayBadge";
36	import { ShortcutsSheet } from "./components/ShortcutsSheet";
37	import { VerdictCard } from "./components/VerdictCard";
38	import "./components/generationDock.css";
39	import { MapCanvas } from "./graph/Canvas";
40	import { bothPaintings, type Engine, railRows } from "./graph/diff/branchWorld";
41	import { endings, NO_SUMMARY_YET } from "./graph/diff/endings";
42	import { tileHeight } from "./graph/geometry";
43	import type { MapKeys } from "./keyboard/useMapKeys";
44	import { generate } from "./stream/generate";
45	import type { Growth } from "./stream/growth";
46	import { fold, waitingFor } from "./stream/growth";
47	import type { Readiness } from "./stream/readiness";
48	import { withRecordings } from "./stream/readiness";
49	import type { Working } from "./stream/transcript";
50	import { readTranscript } from "./stream/transcript";
51	import {
52	  type Absence,
53	  ApiWorldSource,
54	  appendEdit,
55	  type BranchView,
56	  branchesOf,
57	  type ClaimView,
58	  type DiffView,
59	  type Edit,
60	  FixtureWorldSource,
61	  forkBranch,
62	  type Known,
63	  type LinkView,
64	  openBranch,
65	  type Ranged,
66	  type Reason,
67	  type Selection,
68	  type WorldSource,
69	  type WorldView,
70	  workshopOf,
71	} from "./world";
72	
73	/**
74	 * Everything the screen can know about one thing it asked for. Three states and
75	 * no others, which is what makes every pixel below traceable to a cause.
76	 */
77	type Answer<Reading> =
78	  | { state: "asking" }
79	  | { state: "answered"; value: Reading }
80	  | { state: "failed"; reason: string };
81	
82	/** How loud a row's words are. Emphasis only — the words carry the meaning. */
83	type Tone = "good" | "quiet" | "loud";
84	
85	/** One row of the strip at the foot of the launchpad. */
86	interface Reading {
87	  /** What is being reported, such as "server". */
88	  label: string;
89	  /** The value from the server, or null while the request is still in flight. */
90	  value: string | null;
91	  /** A mark beside the words. Never the only carrier of meaning. */
92	  glyph: string;
93	  /** What the value means, in plain words. On a failure, this is the failure. */
94	  state: string;
95	  tone: Tone;
96	}
97	
98	/** Turn whatever a failed request threw into one sentence. */
99	function inWords(reason: unknown): string {
100	  return reason instanceof Error ? reason.message : "The reason was not recorded.";
101	}
102	
103	/**
104	 * Ask what this copy can do, and read the list of recordings off the answer.
105	 *
106	 * Defined at module level because the hook below runs it once and needs the same
107	 * function on every render.
108	 */
109	function askReadiness(): Promise<Readiness> {
110	  return readReadiness().then(withRecordings);
111	}
112	
113	/**
114	 * Make one request when the screen first appears and report where it got to.
115	 *
116	 * @param ask The request to make. It must be the same function on every render,
117	 *   so pass one defined at module level rather than one written inline.
118	 */
119	function useAnswer<Reading>(ask: () => Promise<Reading>): Answer<Reading> {
120	  const [answer, setAnswer] = useState<Answer<Reading>>({ state: "asking" });
121	
122	  useEffect(() => {
123	    let stillOnScreen = true;
124	    ask().then(
125	      (value) => {
126	        if (stillOnScreen) {
127	          setAnswer({ state: "answered", value });
128	        }
129	      },
130	      (reason: unknown) => {
131	        if (stillOnScreen) {
132	          setAnswer({ state: "failed", reason: inWords(reason) });
133	        }
134	      },
135	    );
136	    return () => {
137	      stillOnScreen = false;
138	    };
139	  }, [ask]);
140	
141	  return answer;
142	}
143	
144	/** The row that says whether the server answered at all. */
145	function serverReading(answer: Answer<Health>): Reading {
146	  switch (answer.state) {
147	    case "asking":
148	      return {
149	        label: "server",
150	        value: null,
151	        glyph: "○",
152	        state: "asking the server",
153	        tone: "quiet",
154	      };
155	    case "answered":
156	      return {
157	        label: "server",
158	        value: answer.value.status,
159	        glyph: "●",
160	        state: "reachable",
161	        tone: "good",
162	      };
163	    case "failed":
164	      return { label: "server", value: "—", glyph: "○", state: answer.reason, tone: "loud" };
165	  }
166	}
167	
168	/** The row that says whether a key for the language model is configured. */
169	function modelKeyReading(answer: Answer<Readiness>): Reading {
170	  switch (answer.state) {
171	    case "asking":
172	      return {
173	        label: "model key",
174	        value: null,
175	        glyph: "○",
176	        state: "asking the server",
177	        tone: "quiet",
178	      };
179	    case "answered":
180	      return answer.value.model_key_present
181	        ? {
182	            label: "model key",
183	            value: "present",
184	            glyph: "●",
185	            state: "ready to generate",
186	            tone: "good",
187	          }
188	        : {
189	            label: "model key",
190	            value: "absent",
191	            glyph: "○",
192	            state:
193	              answer.value.replayable.length === 0
194	                ? "no key configured, and nothing recorded to play instead"
195	                : `no key configured — ${answer.value.replayable.length} example(s) play from recordings`,
196	            tone: "quiet",
197	          };
198	    case "failed":
199	      return { label: "model key", value: "—", glyph: "○", state: answer.reason, tone: "loud" };
200	  }
201	}
202	
203	/** The row that says which build answered. */
204	function versionReading(answer: Answer<About>): Reading {
205	  switch (answer.state) {
206	    case "asking":
207	      return {
208	        label: "version",
209	        value: null,
210	        glyph: "○",
211	        state: "asking the server",
212	        tone: "quiet",
213	      };
214	    case "answered":
215	      return {
216	        label: "version",
217	        value: answer.value.version,
218	        glyph: "●",
219	        state: `reported by ${answer.value.name}`,
220	        tone: "good",
221	      };
222	    case "failed":
223	      return { label: "version", value: "—", glyph: "○", state: answer.reason, tone: "loud" };
224	  }
225	}
226	
227	/**
228	 * One row: a label, the value the server gave, and what that value means.
229	 *
230	 * While the value is missing the cell holds a bar of the same height, so the
231	 * row does not change size when the answer arrives. There is no spinner: a bar
232	 * where the value will land says the same thing without pretending to spin.
233	 */
234	function StatusRow({ reading }: { reading: Reading }) {
235	  const waiting = reading.value === null;
236	  return (
237	    <div className="status-row">
238	      <dt className="status-label">{reading.label}</dt>
239	      <dd className="status-value" data-settled={waiting ? "no" : "yes"}>
240	        {waiting ? <span className="placeholder" aria-hidden="true" /> : reading.value}
241	      </dd>
242	      <dd className="status-state" data-tone={reading.tone}>
243	        <span className="glyph" aria-hidden="true">
244	          {reading.glyph}
245	        </span>
246	        <span className="state-words">{reading.state}</span>
247	      </dd>
248	    </div>
249	  );
250	}
251	
252	/** Which of the screens is showing. */
253	type Screen =
254	  | { at: "launchpad" }
255	  | { at: "opening"; id: string }
256	  /** A map being built in front of the reader, from a sentence they typed. */
257	  | { at: "growing"; asked: Asked }
258	  | {
259	      at: "map";
260	      world: WorldView;
261	      branches: readonly BranchView[];
262	      /**
263	       * Why the map on screen was read from the stored example rather than
264	       * worked out by the engine, or nothing when the engine answered.
265	       */
266	      insteadOfTheEngine: string | null;
267	    }
268	  | { at: "failed"; id: string; reason: string };
269	
270	/** How long the wires take to arrive, column by column, before the map settles. */
271	const WAVE_SETTLES_AFTER = 1200;
272	
273	/**
274	 * What stands where a likelihood would go while the engine is being asked for
275	 * one.
276	 *
277	 * The shared vocabulary has three ways of saying a number is not there, and
278	 * this is the third of them — *nothing has been computed* — because that is
279	 * exactly what is true while a question is in flight: the engine has been asked
280	 * and has not answered, so nothing has worked this number through the map
281	 * **yet**. It is not a fourth kind of absence and it is not a spinner: the map
282	 * on screen keeps its shape, the slots that will move say why they are empty,
283	 * and the line under the map says what has been asked for and where.
284	 */
285	const WHILE_ASKING: Absence = {
286	  kind: "no_engine",
287	  words: "no engine yet",
288	  reason:
289	    "The engine has been asked at /api/worlds for the map with this branch folded onto it, and " +
290	    "has not answered. Nothing has worked this number through the map yet.",
291	};
292	
293	/**
294	 * What stands where a likelihood would go when the engine **refused** the
295	 * branch.
296	 *
297	 * Not "no engine yet": the engine is there and it answered — it said the branch
298	 * does not fit the map, and it said why. The words have to be true of that, and
299	 * the vocabulary's first three rows are all about a number nobody has worked out
300	 * rather than one that could not be. So there is a **fourth row** — *the engine
301	 * refused the branch these numbers would come from* → **not worked out** — and a
302	 * kind of its own to go with it, because "nothing has run yet" invites waiting
303	 * and "the engine turned this down" invites repairing what it turned down.
304	 */
305	const REFUSED: Absence = {
306	  kind: "refused",
307	  words: "not worked out",
308	  reason:
309	    "The engine would not work this map out from this branch: the branch does not fit the map. " +
310	    "Every reason is beside the map, and nothing on the map has changed.",
311	};
312	
313	/**
314	 * What stands there when the engine could not be reached at all.
315	 *
316	 * The same words and the same kind as a refusal, because from this slot's point
317	 * of view the two are one fact: the engine was asked for this number and did not
318	 * work it out. What differs is the reason beside them, and the reason is the
319	 * sentence the failure itself arrived with.
320	 */
321	function unreachable(reason: string): Absence {
322	  return {
323	    kind: "refused",
324	    words: "not worked out",
325	    reason: `The engine did not answer, so this number was never worked out. ${reason}`,
326	  };
327	}
328	
329	/**
330	 * Everything the engine has said about the branch that is open, and whether it
331	 * has said it yet.
332	 */
333	type Answered =
334	  | { at: "asking" }
335	  | { at: "answered"; computed: { now: WorldView; change: DiffView } }
336	  | { at: "refused"; reasons: readonly Reason[] }
337	  | { at: "failed"; reason: string }
338	  | { at: "nothing-open" };
339	
340	/**
341	 * Where the engine has got to, in the one shape the picture reads.
342	 *
343	 * Every state but *nothing is open* reserves the room an answer will take and
344	 * says why it is not there yet, so the map is the same size before and after the
345	 * answer lands and nothing on it jumps.
346	 */
347	function engineState(answer: Answered): Engine | undefined {
348	  switch (answer.at) {
349	    case "answered":
350	      return { at: "answered", now: answer.computed.now, change: answer.computed.change };
351	    case "asking":
352	      return { at: "waiting", absence: WHILE_ASKING };
353	    case "refused":
354	      return { at: "waiting", absence: REFUSED };
355	    case "failed":
356	      return { at: "waiting", absence: unreachable(answer.reason) };
357	    case "nothing-open":
358	      return undefined;
359	  }
360	}
361	
362	/**
363	 * How tall a box this claim's tile needs, with room for how far its number
364	 * moved.
365	 *
366	 * A tile is as tall as its own content, and the layout has to know that before
367	 * the browser has drawn one — so the height is a plain function of the claim.
368	 * This adds one thing to it: **how far the number moved gets a line of its own**
369	 * under whatever the edits had to say. On the busiest tile on the map, *Supposed
370	 * · Oct 1 → Retracted · Oct 2 · by "…"* already runs to three lines, and
371	 * stringing a reading on the end of that run pushes a line out of the box.
372	 *
373	 * The extra line is measured rather than written down: the words' block and the
374	 * reading's block are each measured on their own and the empty tile is counted
375	 * once. So if the badge line height ever changes, this changes with it, and
376	 * there is no second copy of a number here to fall out of step.
377	 *
378	 * @param claim The claim the tile is for.
379	 */
380	function roomFor(claim: ClaimView): number {
381	  const badges = claim.badges ?? [];
382	  const said = badges.filter((badge) => badge.movement !== true);
383	  const moved = badges.filter((badge) => badge.movement === true);
384	  if (said.length === 0 || moved.length === 0) {
385	    return tileHeight(claim);
386	  }
387	  const withWords = tileHeight({ ...claim, badges: said });
388	  const withReading = tileHeight({ ...claim, badges: moved });
389	  const withNeither = tileHeight({ ...claim, badges: [] });
390	  return withWords + withReading - withNeither;
391	}
392	
393	/** Turn whatever the engine threw into either a list of reasons or one sentence. */
394	function asAnswer(reason: unknown): Answered {
395	  if (reason instanceof RefusedBranch) {
396	    return { at: "refused", reasons: reason.reasons };
397	  }
398	  return { at: "failed", reason: inWords(reason) };
399	}
