910	/* ---- A map being built in front of you ----------------------------------- */
911	
912	/**
913	 * Run one generation and fold what comes back into what the screen knows.
914	 *
915	 * **No component talks to the network**: this hook holds the one request, and
916	 * everything on screen is drawn from the state it folds. The run stops when the
917	 * reader leaves the page, which is what stops the spending — the route checks
918	 * whether the client is still there before its next model call.
919	 *
920	 * @param asked The sentence, the destination if there was one, and the reader's
921	 *   own likelihood if they gave one.
922	 */
923	function useGeneration(asked: Asked): Growth {
924	  const [growth, setGrowth] = useState<Growth>(() => waitingFor(asked.hypothesis, asked.target));
925	
926	  useEffect(() => {
927	    const stop = new AbortController();
928	    let stillOnScreen = true;
929	    setGrowth(waitingFor(asked.hypothesis, asked.target));
930	
931	    const run = async (): Promise<void> => {
932	      const stream = generate(
933	        {
934	          hypothesis: asked.hypothesis,
935	          ...(asked.target === null ? {} : { target: asked.target }),
936	          // "I don't know" sends nothing at all. Not a half, not a wide band.
937	          ...(asked.belief === null ? {} : { user_belief: asked.belief }),
938	        },
939	        { signal: stop.signal },
940	      );
941	      for await (const event of stream) {
942	        if (!stillOnScreen) {
943	          return;
944	        }
945	        setGrowth((was) => fold(was, event));
946	      }
947	    };
948	
949	    run().catch((failure: unknown) => {
950	      if (!stillOnScreen) {
951	        return;
952	      }
953	      // Never reaching the route at all is the one thing that is not an event:
954	      // there is no stream to read and nothing to draw, so it is folded in by
955	      // hand as the sentence the failure arrived with.
956	      setGrowth((was) => fold(was, { event: "failed", message: inWords(failure) }));
957	    });
958	
959	    return () => {
960	      stillOnScreen = false;
961	      stop.abort();
962	    };
963	  }, [asked.hypothesis, asked.target, asked.belief]);
964	
965	  return growth;
966	}
967	
968	/**
969	 * The screen a map builds itself on.
970	 *
971	 * The same canvas, the same panel and the same keyboard as every other map. What
972	 * is different is where the map comes from: it arrives claim by claim down one
973	 * request, with a reserved rectangle standing wherever the next one will go, and
974	 * every proposal the rules refused listed beside it.
975	 *
976	 * **There is no spinner here, and no moment where a blank screen turns into a
977	 * finished picture.** The growing *is* the loading state.
978	 */
979	function GenerationScreen({
980	  asked,
981	  replaying,
982	  onLeave,
983	}: {
984	  asked: Asked;
985	  /**
986	   * True when this copy has no model key, so the run is a recording being played
987	   * back. Known before the stream says anything, which is why the badge can be
988	   * on screen from the first frame.
989	   */
990	  replaying: boolean;
991	  onLeave: () => void;
992	}) {
993	  const growth = useGeneration(asked);
994	  const [selection, setSelection] = useState<Selection>(null);
995	  const [focused, setFocused] = useState<string | null>(null);
996	  const [overlay, setOverlay] = useState<"sheet" | null>(null);
997	  const [dock, setDock] = useState<"panel" | "outline">("panel");
998	  const [openAt, setOpenAt] = useState<number | null>(null);
999	  const [status, setStatus] = useState(
1000	    "Press ? for every key. j and k walk a column; h and l follow the wires.",
1001	  );
1002	  const [working, setWorking] = useState<Working>({ state: "reading" });
1003	
1004	  const { generationId, phase } = growth;
1005	  const finished = phase === "settled" || phase === "stopped" || phase === "failed";
1006	
1007	  // The working of the run, read once the run has finished. It is asked for then
1008	  // rather than as it goes, because the server writes it from the same pass that
1009	  // writes the stream and a half-read one would be a second, staler copy.
1010	  useEffect(() => {
1011	    if (generationId === null || !finished) {
1012	      return;
1013	    }
1014	    let stillWanted = true;
1015	    readTranscript(generationId).then((read) => {
1016	      if (stillWanted) {
1017	        setWorking(read);
1018	      }
1019	    });
1020	    return () => {
1021	      stillWanted = false;
1022	    };
1023	  }, [generationId, finished]);
1024	
1025	  const outline = useMemo(() => outlineOf(growth.world), [growth.world]);
1026	  const announcement = useMemo(() => growthAnnouncement(growth), [growth]);
1027	
1028	  // The keyboard follows the growing edge: a claim that has just arrived takes
1029	  // focus, exactly as a claim a branch adds does. That is what keeps the newest
1030	  // tile on the glass through a run that goes on for minutes — the canvas
1031	  // already brings whatever the keyboard is on into view, so nothing here
1032	  // re-frames the map and nothing re-lays it out. A tile that is already placed
1033	  // stays exactly where it is; what moves is where the reader is looking.
1034	  // A claim that has just **arrived** takes focus, and nothing else does. The
1035	  // count is what says one arrived: when the likelihoods land, the engine's own
1036	  // world replaces the drawing and its claims come back in the map's order
1037	  // rather than the order they were proposed in — which is not an arrival, and
1038	  // moving the view for it would slide the map sideways at the very moment it
1039	  // stopped changing.
1040	  const howManyClaims = growth.world.claims.length;
1041	  const seenSoFar = useRef(0);
1042	  const lastArrived = useRef<string | null>(null);
1043	  useEffect(() => {
1044	    if (howManyClaims <= seenSoFar.current) {
1045	      return;
1046	    }
1047	    seenSoFar.current = howManyClaims;
1048	    const arrived = growth.world.claims[howManyClaims - 1]?.id ?? null;
1049	    lastArrived.current = arrived;
1050	    setFocused(arrived);
1051	  }, [howManyClaims, growth.world.claims]);
1052	
1053	  // And it lets go the moment the run stops. Focus is also what the hover lens
1054	  // reads, and a lens left on a claim the machine chose would dim the whole
1055	  // finished map to fifteen per cent at exactly the moment the reader starts
1056	  // reading it. If the reader has moved since, their focus is theirs and stays.
1057	  useEffect(() => {
1058	    if (!finished) {
1059	      return;
1060	    }
1061	    setFocused((was) => (was === lastArrived.current ? null : was));
1062	  }, [finished]);
1063	
1064	  const pick = useCallback((id: string) => {
1065	    setFocused(id);
1066	    setSelection({ kind: "claim", id });
1067	  }, []);
1068	
1069	  // Nothing on this screen is bound to the map's own six operations yet, so the
1070	  // keys that open them say so rather than doing nothing.
1071	  const keys: MapKeys = useMemo(
1072	    () => ({
1073	      intervene: () => setStatus("a generated map takes edits through Add a claim, beside the map"),
1074	      branch: () => setStatus("a branch is started on a stored map; this one is still being built"),
1075	      flipWorlds: () => setStatus("there is nothing to flip to — no branch is open"),
1076	      outline: () =>
1077	        setDock((was) => {
1078	          const next = was === "outline" ? "panel" : "outline";
1079	          setStatus(next === "outline" ? "the map as a list" : "the panel beside the map");
1080	          return next;
1081	        }),
1082	      panel: () => setStatus("the panel is beside the map"),
1083	      palette: () => setOverlay("sheet"),
1084	    }),
1085	    [],
1086	  );
1087	
1088	  return (
1089	    <main className="page page--map">
1090	      <header className="map-bar">
1091	        <button className="map-bar__back" type="button" onClick={onLeave}>
1092	          <span aria-hidden="true">←</span> Back to the launchpad
1093	        </button>
1094	        <h1 className="map-bar__title">{growth.world.title}</h1>
1095	        <p className="map-bar__where">
1096	          {/* Nothing sits over the map: the mark that says this run is a
1097	              recording is a badge up here, and the sentence explaining it is in
1098	              the line under the map with every other sentence about where this
1099	              map came from. */}
1100	          {replaying ? (
1101	            <ReplayBadge
1102	              recordingDate={growth.receipt?.recording_date ?? null}
1103	              receiptMode={growth.receipt?.mode ?? null}
1104	            />
1105	          ) : null}
1106	          {asked.target === null ? "Explore" : "Verify"}
1107	          <span className="map-bar__side">
1108	            {asked.target === null ? "what your sentence would cause" : asked.target}
1109	          </span>
1110	        </p>
1111	        <button className="map-bar__sheet" type="button" onClick={() => setOverlay("sheet")}>
1112	          Every key (?)
1113	        </button>
1114	      </header>
1115	
1116	      <div className="map-body">
1117	        <div className="map-stage">
1118	          <MapCanvas
1119	            world={growth.world}
1120	            selection={selection}
1121	            onSelect={setSelection}
1122	            focused={focused}
1123	            onFocused={setFocused}
1124	            mapKey={generationId ?? "a run that has not started"}
1125	            keys={keys}
1126	            onStatus={setStatus}
1127	            onOverflow={() => setStatus("every claim is in the list beside the map")}
1128	            arriving={!finished}
1129	            reserved={growth.skeletons}
1130	            // Framed once when the first rectangle is drawn, and once more when
1131	            // the run stops — the one moment nothing on the map is moving and
1132	            // the reader is about to start reading it.
1133	            frameAgainOn={finished ? "the run stopped" : undefined}
1134	          />
1135	          {overlay === "sheet" ? (
1136	            <ShortcutsSheet open={true} onClose={() => setOverlay(null)} />
1137	          ) : null}
1138	          <p className="map-status">
1139	            <span className="map-status__mark">last key</span>
1140	            {status}
1141	          </p>
1142	        </div>
1143	
1144	        <aside className="dock dock--generation" aria-label="The panel beside the map">
1145	          {/* The map as a list, in place of the panel, exactly as it is on a
1146	              stored map: press O for it, press O again for the panel. It grows
1147	              as the map grows, in the same causal order, so a reader who never
1148	              sees the canvas hears the map being built rather than a silence
1149	              followed by a finished list. */}
1150	          {dock === "outline" ? (
1151	            <Outline items={outline} onPick={pick} focused={focused} />
1152	          ) : (
1153	            <>
1154	              {/* The Verify door's answer, at the top, when a destination was named. */}
1155	              {growth.verdict === null || asked.target === null ? null : (
1156	                <VerdictCard
1157	                  verdict={growth.verdict}
1158	                  target={asked.target}
1159	                  world={growth.world}
1160	                  onSelect={pick}
1161	                />
1162	              )}
1163	
1164	              <RefusalStrip
1165	                refusals={growth.refusals}
1166	                finished={finished}
1167	                openAt={openAt}
1168	                onOpen={(at) => {
1169	                  setOpenAt(at);
1170	                  setSelection({ kind: "generation", id: generationId ?? "" });
1171	                }}
1172	              />
1173	
1174	              {growth.receipt === null ? null : (
1175	                <ReceiptStrip
1176	                  receipt={growth.receipt}
1177	                  onOpen={() => {
1178	                    setOpenAt(null);
1179	                    setSelection({ kind: "generation", id: generationId ?? "" });
1180	                  }}
1181	                />
1182	              )}
1183	
1184	              {finished && growth.world.baseId !== "" ? (
1185	                // The same control, the same words and the same refusals as the
1186	                // one on a stored map's six-button panel. What differs is only
1187	                // what happens next: a generated map has no branch panel on this
1188	                // screen yet, so the claim is drafted, checked and said, and
1189	                // putting it on a branch of this map is the next piece of work.
1190	                <AddAClaim
1191	                  baseId={growth.world.baseId}
1192	                  andThen="It is checked against this map and ready to go onto a branch of it."
1193	                />
1194	              ) : null}
1195	
1196	              <Inspector
1197	                world={growth.world}
1198	                selection={selection}
1199	                generation={{
1200	                  receipt: growth.receipt,
1201	                  working,
1202	                  unknown: growth.unknown,
1203	                  openAt,
1204	                }}
1205	              />
1206	            </>
1207	          )}
1208	        </aside>
1209	      </div>
1210	
1211	      {/* Said out loud, and said once. On a stored map this line is on the page
1212	          as well; here the same facts are already drawn — the claims on the
1213	          canvas, the refusals in the panel, why the run stopped under the map —
1214	          so printing them again made the foot of the screen three strips of
1215	          prose saying the same thing twice. It stays the spoken channel. */}
1216	      <p className="map-live map-live--spoken" aria-live="polite">
1217	        {announcement}
1218	      </p>
1219	
1220	      <div className="map-origin">
1221	        <p className="map-origin__line">{growth.world.origin}</p>
1222	        {replaying ? (
1223	          <p className="map-origin__line">
1224	            {replaySentence({
1225	              recordingDate: growth.receipt?.recording_date ?? null,
1226	              receiptMode: growth.receipt?.mode ?? null,
1227	            })}
1228	          </p>
1229	        ) : null}
1230	        <DoneLine done={growth.done} failure={growth.failure} />
1231	        {(growth.world.warnings ?? []).map((warning) => (
1232	          <p className="map-origin__line" key={warning}>
1233	            {warning}
1234	          </p>
1235	        ))}
1236	      </div>
1237	    </main>
1238	  );
1239	}
1240	
1241	/**
1242	 * Where maps come from: the engine.
1243	 *
1244	 * Every number on the map is worked out by it, from the stored map, the branch
1245	 * and one seed. Nothing on this screen computes a likelihood, and nothing on
1246	 * this screen shows one the engine did not produce.
1247	 */
1248	const DEFAULT_SOURCE: WorldSource = new ApiWorldSource();
1249	
1250	/**
1251	 * Where maps come from when the engine cannot be reached.
1252	 *
1253	 * A map you can still read beats a blank screen. The stored example's claims,
1254	 * arrows, dates and sources are all real and all still worth reading — what is
1255	 * missing is the working-out, and the screen says so in a line under the map
1256	 * rather than letting a hand-written likelihood pass for a computed one.
1257	 */
1258	const FALLBACK_SOURCE: WorldSource = new FixtureWorldSource();
1259	
1260	/**
1261	 * The line under the map when the stored example is standing in for the engine.
1262	 *
1263	 * @param reason What went wrong, in the sentence the failure arrived with.
1264	 */
1265	function insteadOfTheEngine(reason: string): string {
1266	  return (
1267	    `The engine did not answer, so this map is the stored example exactly as it was written: ` +
1268	    `its claims, arrows, dates and sources are real, and its likelihoods are the illustrative ` +
1269	    `ones somebody wrote down rather than anything worked out. ${reason}`
1270	  );
1271	}
1272	
1273	/** What the screen needs. All three have defaults; all three exist so they can be swapped. */
1274	export interface AppProps {
1275	  /** Where maps and worlds come from. */
1276	  readonly source?: WorldSource;
1277	  /** Where they come from when the first one cannot answer. */
1278	  readonly fallback?: WorldSource;
1279	  /** How the list of stored examples is read. */
1280	  readonly listExamples?: () => Promise<FixtureSummary[]>;
1281	}
1282	
1283	/** The screen. */
1284	export function App({
1285	  source = DEFAULT_SOURCE,
1286	  fallback = FALLBACK_SOURCE,
1287	  listExamples = readExampleList,
1288	}: AppProps = {}) {
1289	  const health = useAnswer(readHealth);
1290	  const readiness = useAnswer(askReadiness);
1291	  const about = useAnswer(readAbout);
1292	  const examples = useAnswer(listExamples);
1293	
1294	  const [screen, setScreen] = useState<Screen>({ at: "launchpad" });
1295	  const [using, setUsing] = useState<WorldSource>(source);
1296	
1297	  const open = useCallback(
1298	    (id: string) => {
1299	      setScreen({ at: "opening", id });
1300	      /**
1301	       * The world and the map's own branches, together: the world is what gets
1302	       * drawn, and the branches are the edits somebody already made to it, which
1303	       * the panel lists and the diff view folds on.
1304	       *
1305	       * @param from Where to ask.
1306	       */
1307	      const ask = (from: WorldSource) =>
1308	        Promise.all([from.readWorld({ baseId: id }), from.readBundle(id)]);
1309	
1310	      ask(source).then(
1311	        ([world, bundle]) => {
1312	          setUsing(source);
1313	          setScreen({ at: "map", world, branches: branchesOf(bundle), insteadOfTheEngine: null });
1314	        },
1315	        (failure: unknown) => {
1316	          // The engine could not answer. Rather than a blank screen, the stored
1317	          // example — and a line under the map saying, in the failure's own
1318	          // words, that these are not computed numbers.
1319	          ask(fallback).then(
1320	            ([world, bundle]) => {
1321	              setUsing(fallback);
1322	              setScreen({
1323	                at: "map",
1324	                world,
1325	                branches: branchesOf(bundle),
1326	                insteadOfTheEngine: insteadOfTheEngine(inWords(failure)),
1327	              });
1328	            },
1329	            // Neither answered, which means the server itself is not there. That
1330	            // is one sentence on the page, and a way back to the launchpad.
1331	            (alsoFailed: unknown) => setScreen({ at: "failed", id, reason: inWords(alsoFailed) }),
1332	          );
1333	        },
1334	      );
1335	    },
1336	    [source, fallback],
1337	  );
1338	
1339	  const toLaunchpad = useCallback(() => setScreen({ at: "launchpad" }), []);
1340	
1341	  /** Build a map from a sentence, and watch it arrive. */
1342	  const build = useCallback((asked: Asked) => setScreen({ at: "growing", asked }), []);
1343	
1344	  const readings = useMemo(
1345	    () => [serverReading(health), modelKeyReading(readiness), versionReading(about)],
1346	    [health, readiness, about],
1347	  );
1348	
1349	  if (screen.at === "growing") {
1350	    return (
1351	      <GenerationScreen
1352	        asked={screen.asked}
1353	        // Known before the stream has said anything, which is the whole reason
1354	        // the badge can be on screen from the first frame. When the receipt
1355	        // arrives it is the authority, and the badge takes its word.
1356	        replaying={readiness.state === "answered" && !readiness.value.model_key_present}
1357	        onLeave={toLaunchpad}
1358	      />
1359	    );
1360	  }
1361	
1362	  if (screen.at === "map") {
1363	    return (
1364	      <MapScreen
1365	        base={screen.world}
1366	        branches={screen.branches}
1367	        source={using}
1368	        insteadOfTheEngine={screen.insteadOfTheEngine}
1369	        onLeave={toLaunchpad}
1370	      />
1371	    );
1372	  }
1373	
1374	  if (screen.at !== "launchpad") {
1375	    return (
1376	      <main className="page page--map">
1377	        <header className="map-bar">
1378	          <button className="map-bar__back" type="button" onClick={toLaunchpad}>
1379	            <span aria-hidden="true">←</span> Back to the launchpad
1380	          </button>
1381	          <h1 className="map-bar__title">Strait of Hormuz</h1>
1382	        </header>
1383	
1384	        <div className="map-waiting">
1385	          <p className="map-waiting__line">
1386	            {screen.at === "opening"
1387	              ? `Reading the map from /api/fixtures/${screen.id} and asking /api/worlds to work ` +
1388	                `its likelihoods through.`
1389	              : screen.reason}
1390	          </p>
1391	        </div>
1392	      </main>
1393	    );
1394	  }
1395	
1396	  return (
1397	    <main className="page">
1398	      {/* The first screen is the one wide column in this product: it holds the
1399	          two doors, a map that is already drawn, the four sentences from the
1400	          brief and the field you type your own into, and stacking all of that
1401	          in the 660-pixel measure the rest of the page reads at pushes the
1402	          field below the fold. `launchpad.css` owns the width. */}
1403	      <div className="column column--launchpad">
1404	        <header className="masthead">
1405	          <h1 className="wordmark">Katalyst</h1>
1406	          <p className="purpose">
1407	            Type an event you think will happen. See what it would cause, step by step, ending in
1408	            trades.
1409	          </p>
1410	        </header>
1411	
1412	        <Launchpad
1413	          examples={examples.state === "answered" ? examples.value : null}
1414	          failure={examples.state === "failed" ? examples.reason : null}
1415	          readiness={readiness.state === "answered" ? readiness.value : null}
1416	          onOpen={open}
1417	          onBuild={build}
1418	        />
1419	
1420	        <section aria-labelledby="status-heading">
1421	          <h2 className="section-heading" id="status-heading">
1422	            What this build can do right now
1423	          </h2>
1424	          <dl className="status-strip">
1425	            {readings.map((reading) => (
1426	              <StatusRow key={reading.label} reading={reading} />
1427	            ))}
1428	          </dl>
1429	          <p className="provenance">
1430	            Every reading above came from the server, at <code>/api/healthz</code>,{" "}
1431	            <code>/api/readyz</code> and <code>/api/about</code>. The examples came from{" "}
1432	            <code>/api/fixtures</code>. Nothing on this screen is written into the page.
1433	          </p>
1434	        </section>
1435	      </div>
1436	    </main>
1437	  );
1438	}
1439

