1	/**
2	 * The map: tiles, wires, panning and zooming.
3	 *
4	 * The drawing library owns four things and no more — panning, zooming, working
5	 * out what is under the pointer, and the sockets on the sides of a tile.
6	 * Everything you can see is ours. That is why only the library's bare
7	 * stylesheet is imported below and never its full one: the full one carries the
8	 * library's own look, and a tool that looks like the library it was built with
9	 * looks like a demo. A check in `npm run lint` fails the build if the full one
10	 * ever appears in this tree.
11	 *
12	 * Three things this file works out that no single wire could work out for
13	 * itself, because a wire cannot see where the other tiles are:
14	 *
15	 *   1. **How each wire is routed.** Most arrows join neighbouring columns and
16	 *      take the ordinary route. An arrow that skips a column would run straight
17	 *      through the tile in between and disappear behind it, so it is given a
18	 *      clear corridor to travel along instead; and the one arrow that runs
19	 *      backwards is sent over the top of the map, where there is nothing to
20	 *      cross.
21	 *   2. **The hover lens.** Point at a claim and everything not on its path —
22	 *      neither one of its causes nor one of the things it causes — drops to
23	 *      fifteen per cent.
24	 *   3. **Whether a wire's plate has room for its words.** Below the same zoom at
25	 *      which a tile switches to its summary, a plate's words would land under
26	 *      eleven pixels on the glass, so the plates go. Nothing is scaled down to
27	 *      dodge the rule.
28	 */
29	
30	import {
31	  Background,
32	  BackgroundVariant,
33	  Controls,
34	  ReactFlow,
35	  ReactFlowProvider,
36	  useReactFlow,
37	  useStore,
38	} from "@xyflow/react";
39	import { type ReactNode, useCallback, useEffect, useMemo, useRef, useState } from "react";
40	import "@xyflow/react/dist/base.css";
41	import { SkeletonTile } from "../components/SkeletonTile";
42	import { Tile } from "../components/Tile";
43	import { TileOverflow } from "../components/TileOverflow";
44	import type { MapKeys } from "../keyboard/useMapKeys";
45	import { useMapKeys } from "../keyboard/useMapKeys";
46	import type { Selection, WorldView } from "../world";
47	import { NOT_ON_THIS_MAP } from "../world/naming";
48	import {
49	  firstFrame,
50	  LARGEST_ZOOM,
51	  SMALLEST_ZOOM,
52	  SUMMARY_BELOW_ZOOM,
53	  TILE_WIDTH,
54	} from "./geometry";
55	import { assignLayers } from "./layers";
56	import { useLayout } from "./layoutRunner";
57	import {
58	  type ClaimNode,
59	  type MapEdge,
60	  type MapNode,
61	  OVERFLOW_PREFIX,
62	  type OverflowNode,
63	  RESERVED_PREFIX,
64	  type ReservedBox,
65	  type SkeletonNode,
66	  toFlow,
67	} from "./toFlow";
68	import { CausalWire } from "./wires/CausalWire";
69	import { onThePathFrom } from "./wires/lens";
70	import { planPlates } from "./wires/plates";
71	import { type Box, planRoutes, SKY_GAP, tailOffsets } from "./wires/route";
72	import { ARROWHEAD, WireMarks } from "./wires/WireMarks";
73	import "./canvas.css";
