75	/** The two kinds of box the map draws. Defined once, outside render, so the
76	 * drawing library never has to rebuild its tiles because the object changed. */
77	const TILE_TYPES = {
78	  claim: ({ data }: { data: ClaimNode["data"] }) => (
79	    <Tile
80	      claim={data.claim}
81	      isHypothesis={data.isHypothesis}
82	      versions={data.versions}
83	      height={data.height}
84	    />
85	  ),
86	  overflow: ({ data }: { data: OverflowNode["data"] }) => <TileOverflow count={data.count} />,
87	  skeleton: ({ data }: { data: SkeletonNode["data"] }) => <SkeletonTile words={data.words} />,
88	};
