93	/** What the map needs beyond the world it draws. */
94	interface SurfaceProps {
95	  /** The world to draw. */
96	  readonly world: WorldView;
97	  /** What the panel beside the map is open on. */
98	  readonly selection: Selection;
99	  /** Called when the reader selects a claim or an arrow, by pointer or by keyboard. */
100	  readonly onSelect: (selection: Selection) => void;
101	  /** Which claim the keyboard is on. Held outside the map, because the keys are. */
102	  readonly focused: string | null;
103	  /** Put the keyboard on a claim. */
104	  readonly onFocused: (id: string | null) => void;
105	  /**
106	   * How tall to draw each tile, when a diff needs one box to hold two paintings.
107	   * Left out, each tile is as tall as its own content.
108	   */
109	  readonly heights?: ReadonlyMap<string, number>;
110	  /**
111	   * Which map this is: the base map, or the base map with one branch folded on.
112	   *
113	   * Both paintings of one diff share it, so flipping between them moves nothing.
114	   * Opening a different branch changes it, and the union of the two worlds is
115	   * then laid out again from scratch — one layout, two paintings.
116	   */
117	  readonly mapKey: string;
118	  /** Everything the keys that are not about moving are wired to. */
119	  readonly keys: MapKeys;
120	  /** Say what the last keystroke did, under the map. */
121	  readonly onStatus: (line: string) => void;
122	  /**
123	   * The reader asked to see the claims a column had no room for.
124	   *
125	   * The collapsed tile does not expand: it opens the outline, filtered to that
126	   * column. The outline is built from the world rather than from what is
127	   * painted, so those claims already have items there and the tile only has to
128	   * point at them.
129	   */
130	  readonly onOverflow: (column: { layer: number; claims: readonly string[] }) => void;
131	  /**
132	   * True while the map is arriving, which is when the one animation it spends on
133	   * causality runs: the wires draw in the order the argument runs, a column at a
134	   * time. Under reduced motion the ordering survives and the drawing goes.
135	   */
136	  readonly arriving: boolean;
137	  /**
138	   * The rectangles the map is holding open at its growing edge, while a map is
139	   * still being built.
140	   *
141	   * Empty on every finished map, which is every map this canvas drew before
142	   * generation existed — so nothing about a stored example changes.
143	   */
144	  readonly reserved?: readonly ReservedBox[];
145	  /**
146	   * What the canvas says about the session it is in, such as that this run is a
147	   * recording being played back. Drawn in the corner of the surface, over
148	   * nothing.
149	   */
150	  readonly badge?: ReactNode;
151	  /**
152	   * A word that changes when the map should be framed again.
153	   *
154	   * The map is framed once, when it is first drawn, and never again — losing
155	   * your place because the map was rearranged is the most disorienting thing a
156	   * canvas can do. A map that **builds itself** has one more moment worth
157	   * framing: the one where it stops. Nothing on it moves then, the reader is
158	   * about to start reading, and a four-column map framed for its first single
159	   * rectangle is a map they would otherwise have to hunt around.
160	   *
161	   * It is a word rather than a flag so that the effect has something to compare:
162	   * the map is framed once for each value it has ever had.
163	   */
164	  readonly frameAgainOn?: string;
165	}
