167	/** The surface itself. Lives inside the provider so it can move the view. */
168	function MapSurface({
169	  world,
170	  selection,
171	  onSelect,
172	  focused,
173	  onFocused,
174	  heights,
175	  mapKey,
176	  keys,
177	  onStatus,
178	  onOverflow,
179	  arriving,
180	  reserved,
181	  badge,
182	  frameAgainOn,
183	}: SurfaceProps) {
184	  const flow = useReactFlow();
185	  const surface = useRef<HTMLDivElement>(null);
186	  const [pointingAt, setPointingAt] = useState<string | null>(null);
187	
188	  const drawing = useMemo(() => toFlow(world, heights, reserved), [world, heights, reserved]);
189	  const layout = useLayout(drawing.tiles, drawing.layoutEdges, mapKey);
190	
191	  // How far the map is zoomed out. Below the threshold a wire's plate would
192	  // have its words drawn under eleven pixels on the glass, which is the one
193	  // thing nothing in this product is allowed to do, so the plates go and the
194	  // stroke keeps saying what kind of push each wire is.
195	  const zoom = useStore((state) => state.transform[2]);
196	  const tooSmallForWords = zoom < SUMMARY_BELOW_ZOOM;
197	
198	  /** How tall a tile turned out to be, so the view can be centred on its middle. */
199	  const heightOf = useCallback(
200	    (id: string) => drawing.tiles.find((tile) => tile.id === id)?.height ?? 0,
201	    [drawing],
202	  );
203	
204	  /** Where every tile ended up, which is what routing a wire needs to know. */
205	  const boxes = useMemo(() => {
206	    const placed = new Map<string, Box>();
207	    for (const [id, at] of layout.positions) {
208	      placed.set(id, { x: at.x, y: at.y, width: TILE_WIDTH, height: heightOf(id) });
209	    }
210	    return placed;
211	  }, [layout, heightOf]);
212	
213	  // What the hover lens leaves lit. `null` is everything, which is what the map
214	  // looks like when the reader is not pointing at anything. The claim the
215	  // keyboard is on counts as being pointed at, so the lens is not a mouse-only
216	  // feature.
217	  const lens = useMemo(() => {
218	    // **The lens only ever reads a claim that is on the map.** A box can leave
219	    // under the pointer — a reserved rectangle becomes a tile, a claim is
220	    // dropped by a branch — and the mouse never leaves it, because there is
221	    // nothing left to leave. What was pointed at is then a name the map does not
222	    // hold, nothing is on its path, and the whole map dims to fifteen per cent
223	    // with nothing lit. That is the lens answering a question about something
224	    // that is not there.
225	    const under = world.claims.some((claim) => claim.id === pointingAt) ? pointingAt : null;
226	    // **While a map is still arriving the lens is off unless the reader points
227	    // at something.** Focus moves by itself on a map that is building — every
228	    // claim that arrives takes it, so the view can follow the growing edge — and
229	    // dimming the rest of the map because the machine moved is the lens
230	    // answering a question nobody asked. Pointing at a tile still works.
231	    return onThePathFrom(under ?? (arriving ? null : focused), world.links);
232	  }, [pointingAt, focused, world.claims, world.links, arriving]);
233	
234	  // Which column each claim sits in, for the one animation this map spends on
235	  // causality: the wires arrive in the order the argument runs, a column at a
236	  // time. The order is read from the map's own shape, never from the clock.
237	  const column = useMemo(() => {
238	    const placed = new Map<string, number>();
239	    for (const one of assignLayers(
240	      world.claims.map((claim) => claim.id),
241	      world.links,
242	    )) {
243	      placed.set(one.id, one.layer);
244	    }
245	    return placed;
246	  }, [world]);
247	
248	  const nodes: MapNode[] = useMemo(
249	    () =>
250	      drawing.nodes.map((node) => {
251	        const ghost = node.type === "claim" && node.data.claim.ghost === true;
252	        return {
253	          ...node,
254	          position: layout.positions.get(node.id) ?? { x: 0, y: 0 },
255	          selected: selection?.kind === "claim" && selection.id === node.id,
256	          // Two classes and not one: the hover lens and the other world are both
257	          // opacity, and a tile that is off the hovered path *and* in the other
258	          // world has to land at the two multiplied together rather than at
259	          // whichever rule happened to win. `canvas.css` multiplies them.
260	          className: [
261	            // A rectangle held open for a claim that has not arrived is never
262	            // dimmed by the lens. The lens answers "what does this have to do
263	            // with anything", and a box standing for a claim that does not exist
264	            // yet is not on anybody's path — dimming it would hide the one thing
265	            // a reader watching a map build itself is waiting for.
266	            lens !== null && !lens.claims.has(node.id) && !node.id.startsWith(RESERVED_PREFIX)
267	              ? "is-dimmed"
268	              : "",
269	            ghost ? "is-ghost" : "",
270	          ]
271	            .filter((one) => one !== "")
272	            .join(" "),
273	        };
274	      }),
275	    [drawing, layout, lens, selection],
276	  );
277	
278	  const edges: MapEdge[] = useMemo(() => {
279	    const routable = drawing.edges.map((edge) => ({
280	      id: edge.id,
281	      source: edge.source,
282	      target: edge.target,
283	      handle: edge.sourceHandle ?? "out-trigger",
284	      reflexive: edge.data?.reflexive === true,
285	      mode: edge.data?.mode ?? "trigger",
286	      strength: edge.data?.strength ?? 0,
287	      lag: edge.data?.lag ?? 0,
288	    }));
289	    const plans = planRoutes(routable, boxes);
290	    const offsets = tailOffsets(routable);
291	    // Where every plate goes, worked out for the whole map at once. A wire
292	    // cannot see its neighbours, and once two worlds are laid over each other
293	    // that is not enough: the union crowds the middle of the map and plates
294	    // began landing on one another.
295	    const plates = planPlates({ wires: routable, boxes, plans, tailOffsets: offsets });
296	    const wires = new Map(world.links.map((link) => [link.id, link]));
297	    return drawing.edges.map((edge) => {
298	      if (edge.data === undefined) {
299	        return edge;
300	      }
301	      const wire = wires.get(edge.id);
302	      return {
303	        ...edge,
304	        selected: selection?.kind === "wire" && selection.id === edge.id,
305	        // The wave's place in the order, and whether this wire belongs to the
306	        // world you are not looking at. Both are carried as classes, because a
307	        // class is what the drawing library puts on the group the wire is drawn
308	        // in, and a wire cannot know where the other wires are.
309	        className: [
310	          `wave-${Math.min(column.get(edge.source) ?? 0, 5)}`,
311	          wire?.ghost === true ? "is-ghost" : "",
312	          wire?.change === undefined ? "" : `is-${wire.change}`,
313	        ]
314	          .filter((one) => one !== "")
315	          .join(" "),
316	        data: {
317	          ...edge.data,
318	          plan: plans.get(edge.id),
319	          tailOffset: offsets.get(edge.id),
320	          plateAt: plates.get(edge.id),
321	          wave: Math.min(column.get(edge.source) ?? 0, 5),
322	          dimmed: lens !== null && !lens.wires.has(edge.id),
323	          tooSmallForWords,
324	        },
325	      };
326	    });
327	  }, [drawing, boxes, lens, selection, tooSmallForWords, world, column]);
328	
329	  /**
330	   * Everything the first frame has to hold: every tile, and the strip of empty
331	   * space above them that the one backwards wire runs along.
332	   */
333	  const mapBounds = useCallback(() => {
334	    const placed = [...layout.positions.entries()];
335	    if (placed.length === 0) {
336	      return null;
337	    }
338	    const left = Math.min(...placed.map(([, at]) => at.x));
339	    const right = Math.max(...placed.map(([, at]) => at.x)) + TILE_WIDTH;
340	    const top = Math.min(...placed.map(([, at]) => at.y));
341	    const bottom = Math.max(...placed.map(([id, at]) => at.y + heightOf(id)));
342	    const overhead = drawing.edges.some((edge) => edge.data?.reflexive === true) ? SKY_GAP + 8 : 0;
343	    return { x: left, y: top - overhead, width: right - left, height: bottom - top + overhead };
344	  }, [drawing, layout, heightOf]);
345	
346	  const framed = useRef<string | null>(null);
347	  const justFramed = useRef(false);
348	  const centredOn = useRef<string | null>(null);
349	
350	  // Frame the map when it is a different map — the first time it is drawn, and
351	  // again when a branch adds a claim to it. Panning, zooming and walking around
352	  // never re-frame: losing your place because the map was rearranged is the most
353	  // disorienting thing a canvas can do.
354	  useEffect(() => {
355	    // Only once the positions really are this map's. Framing from the positions
356	    // worked out for the map before the branch would frame the wrong thing, and
357	    // the right thing would then arrive underneath it.
358	    // Which framing this would be. While a map is being asked to frame again —
359	    // which is only ever when a generation has stopped — the layout's own run
360	    // count is part of the answer, so that a frame taken while the last claims
361	    // were still being placed is taken again when they have been. Nothing lays a
362	    // finished map out again, so this settles after one or two.
363	    const frameFor =
364	      frameAgainOn === undefined ? mapKey : `${mapKey}:${frameAgainOn}:${layout.runs}`;
365	    if (layout.runs === 0 || layout.laidOutFor !== mapKey || framed.current === frameFor) {
366	      return;
367	    }
368	    const frame = mapBounds();
369	    const room = surface.current?.getBoundingClientRect();
370	    if (frame === null || room === undefined) {
371	      return;
372	    }
373	    // Framed to fit — but never zoomed out past the point where a full tile would
374	    // have to become a summary. The reader's first sight of the map is tiles they
375	    // can read; if the whole map does not fit at that size, it is framed from its
376	    // beginning, on the left, where the map starts, and they pan to the rest.
377	    flow.setViewport(firstFrame(frame, { width: room.width, height: room.height }), {
378	      duration: 0,
379	    });
380	    framed.current = frameFor;
381	    justFramed.current = true;
382	  }, [layout.runs, layout.laidOutFor, flow, mapBounds, mapKey, frameAgainOn]);
383	
384	  // The view follows whatever the keyboard is on, so a step along a wire never
385	  // walks off the edge of the glass — and so that a map building itself does not
386	  // build its fourth column off the side of the window while the reader watches
387	  // an empty one. Every claim that arrives takes focus, which is the rule
388	  // `layout-and-zoom.md` already states for a newly created claim; this is the
389	  // other half of the same rule, that the focused tile stays in the viewport.
390	  //
391	  // **It brings the tile in rather than centring on it.** The promise is that
392	  // the focused tile is on the glass, not that it is in the middle of it, and a
393	  // view that recentred on every arrival would yank the map out from under
394	  // somebody reading a tile that was perfectly visible. So: already on the
395	  // glass, nothing happens; off the edge, it is brought to the middle, once.
396	  useEffect(() => {
397	    if (focused === null || layout.runs === 0 || centredOn.current === focused) {
398	      // Only when the keyboard has actually moved. Flipping between the two
399	      // worlds redraws every tile and moves none of them, and a view that slid
400	      // sideways on the flip would make the reader hunt for what changed — which
401	      // is the one thing the flip exists to show.
402	      return;
403	    }
404	    if (justFramed.current) {
405	      justFramed.current = false;
406	      centredOn.current = focused;
407	      return;
408	    }
409	    // Where the layout put it, not where the drawing library thinks it is: a
410	    // tile that has just arrived is in the layout's answer a render before the
411	    // library has it, and reading the library's copy too early gave the origin
412	    // — which is how a map ended up centred on an empty corner.
413	    const at = layout.positions.get(focused);
414	    const room = surface.current?.getBoundingClientRect();
415	    if (at === undefined || room === undefined) {
416	      // Not placed yet. The layout runs again and this runs with it.
417	      return;
418	    }
419	    centredOn.current = focused;
420	
421	    const middle = { x: at.x + TILE_WIDTH / 2, y: at.y + heightOf(focused) / 2 };
422	    const view = flow.getViewport();
423	    const onTheGlass = {
424	      x: at.x * view.zoom + view.x,
425	      y: at.y * view.zoom + view.y,
426	      width: TILE_WIDTH * view.zoom,
427	      height: heightOf(focused) * view.zoom,
428	    };
429	    const inside =
430	      onTheGlass.x >= 0 &&
431	      onTheGlass.y >= 0 &&
432	      onTheGlass.x + onTheGlass.width <= room.width &&
433	      onTheGlass.y + onTheGlass.height <= room.height;
434	    if (inside) {
435	      return;
436	    }
437	    flow.setCenter(middle.x, middle.y, { zoom: view.zoom, duration: 0 });
438	  }, [focused, flow, heightOf, layout]);
439	
440	  /** Show the claims a column had no room for, as a list. */
441	  const openColumn = useCallback(
442	    (layer: number) => {
443	      onOverflow({
444	        layer,
445	        claims: [...column.entries()].filter(([, at]) => at === layer).map(([id]) => id),
446	      });
447	      onStatus(`the claims in column ${layer}, as a list`);
448	    },
449	    [column, onOverflow, onStatus],
450	  );
451	
452	  /**
453	   * What the reader just pointed at, or `null` when it was the empty map.
454	   *
455	   * Read off the page rather than from the drawing library, deliberately. The
456	   * library reports a click on a tile only through the machinery that also drags
457	   * tiles around, and tiles here do not drag — so that report never arrives.
458	   * Asking the page what was under the pointer is one line, and it gives the
459	   * same answer for a wire, a tile and the empty map.
460	   */
461	  const whatIsUnder = useCallback((target: HTMLElement | null): Selection => {
462	    const wire = target?.closest<HTMLElement>(".react-flow__edge");
463	    if (wire?.dataset.id !== undefined) {
464	      return { kind: "wire", id: wire.dataset.id };
465	    }
466	    const tile = target?.closest<HTMLElement>(".react-flow__node");
467	    // A rectangle held open for a claim that has not arrived is a box, not a
468	    // claim: there is nothing behind it to read out, so pressing it does nothing
469	    // and the panel is left where it was.
470	    if (tile?.dataset.id !== undefined && !tile.dataset.id.startsWith(RESERVED_PREFIX)) {
471	      return { kind: "claim", id: tile.dataset.id };
472	    }
473	    return null;
474	  }, []);
475	
476	  /**
477	   * Fill the panel with whatever was pressed, or empty it on a press on the map.
478	   *
479	   * It listens for the press rather than the click, and that is not a detail:
480	   * the drawing library grabs the pointer on the surface the moment a press
481	   * begins, so that dragging the map keeps working when the pointer wanders off
482	   * a tile — and from then on every event, the click included, is reported
483	   * against the surface rather than against what was actually under the pointer.
484	   * The press is the last moment the page can still say what was pressed.
485	   */
486	  const onPointAt = useCallback(
487	    (event: React.PointerEvent<HTMLDivElement>) => {
488	      const under = whatIsUnder(event.target as HTMLElement);
489	      // The zoom buttons and the library's own furniture are not the map.
490	      if (under === null && (event.target as HTMLElement).closest(".react-flow__controls")) {
491	        return;
492	      }
493	      if (under?.kind === "claim" && under.id.startsWith(OVERFLOW_PREFIX)) {
494	        openColumn(Number(under.id.slice(OVERFLOW_PREFIX.length)));
495	        return;
496	      }
497	      onSelect(under);
498	      if (under?.kind === "claim") {
499	        onFocused(under.id);
500	        // Pointing at a tile and reaching it with the keyboard land in the same
501	        // place, so the ring says where you are whichever way you got there.
502	        (event.target as HTMLElement)
503	          .closest<HTMLElement>(".react-flow__node")
504	          ?.focus({ preventScroll: true });
505	      }
506	    },
507	    [onSelect, whatIsUnder, onFocused, openColumn],
508	  );
509	
510	  /**
511	   * Remember what the reader is on, fill the panel with it, and bring it into
512	   * view if it is off the edge of the screen.
513	   *
514	   * This catches the keyboard as well as the pointer. Reaching a claim or an
515	   * arrow with the keyboard and reaching it with the pointer do the same thing:
516	   * the panel beside the map reads it out. Nothing opens over the map, and
517	   * there is nothing to dismiss.
518	   */
519	  const onFocus = useCallback(
520	    (event: React.FocusEvent<HTMLDivElement>) => {
521	      const target = event.target as HTMLElement;
522	      const under = whatIsUnder(target);
523	      if (under === null) {
524	        return;
525	      }
526	      if (under.kind === "wire") {
527	        // **Landing on a wire does not select it, and that is not an
528	        // oversight.** The drawing library rebuilds a wire's element when it
529	        // becomes selected, and rebuilding the element the keyboard is standing
530	        // on drops focus to the page — which made tabbing through the map
531	        // impossible, because the wires come before the tiles. So a wire fills
532	        // the panel when you press Enter on it, and the focus is put back on the
533	        // rebuilt wire straight afterwards, which is what the effect below is
534	        // for. Pointing at one with the mouse is unchanged.
535	        return;
536	      }
537	      onSelect(under);
538	      onFocused(under.id);
539	    },
540	    [onSelect, whatIsUnder, onFocused],
541	  );
542	
543	  // Where every tile ended up, in the shape moving along a wire needs: the
544	  // keyboard asks what it can *walk to*, which reads the whole map, feedback
545	  // arrows included.
546	  const places = useMemo(() => {
547	    const map = new Map<string, { x: number; y: number; height: number }>();
548	    for (const [id, at] of layout.positions) {
549	      map.set(id, { x: at.x, y: at.y, height: heightOf(id) });
550	    }
551	    return map;
552	  }, [layout, heightOf]);
553	
554	  /**
555	   * Find a tile or a wire on the glass by the identifier it carries.
556	   *
557	   * By reading each element's own identifier rather than by asking the page for
558	   * a match: a wire is named after its two ends — `H->B` — and the arrow in the
559	   * middle of that is not a character an address for an element may contain.
560	   */
561	  const onTheGlass = useCallback((kind: "node" | "edge", id: string): HTMLElement | undefined => {
562	    const all = surface.current?.querySelectorAll<HTMLElement>(`.react-flow__${kind}`) ?? [];
563	    return [...all].find((one) => one.dataset.id === id);
564	  }, []);
565	
566	  const claimWords = useCallback(
567	    (id: string) => world.claims.find((claim) => claim.id === id)?.claim ?? NOT_ON_THIS_MAP,
568	    [world],
569	  );
570	
571	  const onKeyDown = useMapKeys({
572	    wires: world.links,
573	    positions: places,
574	    focused,
575	    onFocused: (id) => {
576	      onFocused(id);
577	      // Reaching a tile with the keyboard and reaching it with the pointer do
578	      // the same thing: the panel beside the map reads it out. Nothing opens
579	      // over the map.
580	      onSelect({ kind: "claim", id });
581	      onTheGlass("node", id)?.focus();
582	    },
583	    onStatus,
584	    keys,
585	    words: claimWords,
586	  });
587	
588	  // A wire the reader has just asked for, so that focus can be put back on it
589	  // once the drawing library has rebuilt it.
590	  const askedForWire = useRef<string | null>(null);
591	
592	  // biome-ignore lint/correctness/useExhaustiveDependencies: the selection is not read inside — it is what this is waiting for. The wire is rebuilt because the selection changed, so the selection is exactly the right thing to hang this on.
593	  useEffect(() => {
594	    const id = askedForWire.current;
595	    if (id === null) {
596	      return;
597	    }
598	    askedForWire.current = null;
599	    // Two frames, not none. The drawing library keeps its own record of what is
600	    // selected and rebuilds the wire's element from it a frame later, so putting
601	    // focus back on the element that is there right now would put it on the one
602	    // about to be thrown away.
603	    const frame = requestAnimationFrame(() => {
604	      requestAnimationFrame(() => onTheGlass("edge", id)?.focus());
605	    });
606	    return () => cancelAnimationFrame(frame);
607	  }, [selection, onTheGlass]);
608	
609	  // The keyboard map, bound once on the page. On the page rather than on the map
610	  // itself, because a key bound to the element you happen to be standing on is a
611	  // key that stops working the moment you press Tab — and every key below is left
612	  // alone while the keyboard is in a field.
613	  useEffect(() => {
614	    const onKey = (event: KeyboardEvent): void => {
615	      // A collapsed tile is reached with the keyboard like any other, and Enter
616	      // opens what is behind it — the same thing a press does.
617	      const target = event.target as HTMLElement | null;
618	      const at = target?.closest<HTMLElement>(".react-flow__node");
619	      if (event.key === "Enter" && at?.dataset.id?.startsWith(OVERFLOW_PREFIX) === true) {
620	        event.preventDefault();
621	        openColumn(Number(at.dataset.id.slice(OVERFLOW_PREFIX.length)));
622	        return;
623	      }
624	      // Enter on a wire reads it out in the panel beside the map — the same
625	      // thing pointing at it does. It is Enter rather than merely landing on it
626	      // because of what the comment above `onFocus` explains.
627	      const wire = target?.closest<HTMLElement>(".react-flow__edge");
628	      if ((event.key === "Enter" || event.key === " ") && wire?.dataset.id !== undefined) {
629	        event.preventDefault();
630	        askedForWire.current = wire.dataset.id;
631	        onSelect({ kind: "wire", id: wire.dataset.id });
632	        onStatus(`this arrow, read out in the panel beside the map`);
633	        return;
634	      }
635	      onKeyDown(event);
636	    };
637	    window.addEventListener("keydown", onKey);
638	    return () => window.removeEventListener("keydown", onKey);
639	  }, [onKeyDown, openColumn, onSelect, onStatus]);
640	
641	  return (
642	    <div
643	      className="canvas"
644	      ref={surface}
645	      data-arriving={arriving ? "yes" : "no"}
646	      onFocusCapture={onFocus}
647	      onPointerDownCapture={onPointAt}
648	    >
649	      <WireMarks />
650	
651	      {badge}
652	
653	      <ReactFlow
654	        nodes={nodes}
655	        edges={edges}
656	        nodeTypes={TILE_TYPES}
657	        edgeTypes={WIRE_TYPES}
658	        // Tiles do not move. Automatic layout decides where a claim sits, and a
659	        // tile you can drag half of the time — snapping back whenever the map is
660	        // laid out again — reads as broken. Pinning, grouping and annotating
661	        // arrive later as things you ask for, not as free dragging.
662	        nodesDraggable={false}
663	        nodesConnectable={false}
664	        // A tile and a wire both answer to the pointer and to the keyboard. A
665	        // wire has to: everything it says on the glass it says again in words in
666	        // the panel, and the only way to ask for those words is to reach it.
667	        elementsSelectable={true}
668	        nodesFocusable={true}
669	        edgesFocusable={true}
670	        // Selecting a wire must not lift it above the others. The drawing
671	        // library's default is to re-sort the wires when one is selected so the
672	        // selected one draws on top — and re-sorting them moves the element the
673	        // keyboard is standing on, which drops focus to the page and makes
674	        // tabbing through the map impossible. Nothing here needs the lift: a
675	        // selected wire is marked by a ring, and how wires cross is settled by
676	        // routing rather than by drawing order.
677	        elevateNodesOnSelect={false}
678	        onNodeMouseEnter={(_, node) => setPointingAt(node.id)}
679	        onNodeMouseLeave={() => setPointingAt(null)}
680	        // As far out as the map goes, and no further: past this the summary
681	        // tile's words would be drawn smaller than anything in this product is
682	        // allowed to be.
683	        minZoom={SMALLEST_ZOOM}
684	        maxZoom={LARGEST_ZOOM}
685	        proOptions={{ hideAttribution: false }}
686	        // Named, not addressed: the drawing library writes the address around
687	        // the name itself.
688	        defaultEdgeOptions={{ markerEnd: ARROWHEAD }}
689	      >
690	        <Background variant={BackgroundVariant.Dots} gap={32} size={1} />
691	        <Controls showInteractive={false} position="bottom-left" />
692	      </ReactFlow>
693	
694	      {layout.failure === null ? null : (
695	        <p className="canvas__failure">{`The map could not be laid out. ${layout.failure}`}</p>
696	      )}
697	    </div>
698	  );
699	}
700	
701	/** What the map needs to be dropped into a page. */
702	export type MapCanvasProps = SurfaceProps;
703	
704	/** The map, ready to be dropped into a page. */
705	export function MapCanvas(props: MapCanvasProps) {
706	  return (
707	    <ReactFlowProvider>
708	      <MapSurface {...props} />
709	    </ReactFlowProvider>
710	  );
711	}
