147	  // lists of strings is cheaper and steadier than comparing two arrays by
148	  // identity — a fresh array with the same contents must not start a re-layout.
149	  const shape = useMemo(
150	    () =>
151	      JSON.stringify([
152	        tiles.map((tile) => [tile.id, tile.height]),
153	        edges.map((edge) => [edge.id, edge.source, edge.target]),
154	      ]),
155	    [tiles, edges],
156	  );
