184	    // size is laid out again from scratch: holding a grown tile where its
185	    // shorter self went runs it into whatever sits below.
186	    const holding = pinsFor(placed.current, tiles);
187	    const graph = toElkGraph(
188	      tiles,
189	      wires.map(([id, source, target]) => ({ id, source, target })),
190	      holding,
191	    );
192	    laidOut(graph).then(
193	      (laidOut) => {
194	        if (!stillWanted) {
195	          return;
196	        }
197	        const positions = readPositions(laidOut, holding);
198	        const heights = new Map(tiles.map((tile) => [tile.id, tile.height]));
199	        placed.current = new Map(
200	          [...positions].map(([id, at]) => [id, { at, height: heights.get(id) ?? 0 }]),
201	        );
202	        setLayout((was) => ({
203	          positions,
204	          runs: was.runs + 1,
205	          laidOutFor: mapKey,
206	          failure: null,
207	        }));
208	      },
209	      (reason: unknown) => {
210	        if (stillWanted) {
211	          setLayout((was) => ({ ...was, failure: inWords(reason) }));
212	        }
213	      },
214	    );
215	    return () => {
216	      stillWanted = false;
217	    };
218	  }, [shape, mapKey]);
